"""Export already-scored and fully audited temporal controls, no GT/model work."""
from common import *
import argparse

def run(ds):
 p=validate('temporal_v2');audit=D/f'temporal_v2_{ds}_reporting_receipt.json';a=read(audit);assert a['status']=='verified_whole_domain'and a['score_sha256']==sha(D/f'temporal_v2_{ds}_score_receipt.json');folder=P/'temporal_v2_v2'/ds;r=read(folder/'report.json');rr=read(D/'temporal_v2_v2'/ds/'metrics.json')['private_rows'];pairs=list(r['paired']);tails={}
 for key in pairs:
  left,right=key.split('-');t=[100*(x['values'][left]['t']-x['values'][right]['t'])for x in rr];v=[100*(x['values'][left]['v']-x['values'][right]['v'])for x in rr];tails[key]=dict(severe_t=sum(x< -5 for x in t),severe_v=sum(x< -5 for x in v),severe_union_once=sum(x< -5 or y< -5 for x,y in zip(t,v)),rescue_union_once=sum(x>5 or y>5 for x,y in zip(t,v)),unit='queries;signedleft-right;>5ppthreshold')
 atomic(folder/'all_paired_tail_summary.json',tails)
 def ci(x):return f"{x['mean']:+.6f} [{x['CI95'][0]:.6f}, {x['CI95'][1]:.6f}]"
 s=f"# Complete current-MAP temporal controls: {ds}\n\n**Fully sealed, officially scored and exact-replay audited:** {r['queries']} queries / {r['parents']} parents. Native Source/current FullMAP and all numerical settings remain frozen. Changed posteriors each drive their own joint-MAP interval and a new interval-conditioned exact spatial DP. These are complete inference controls, not fixed boxes with a changed interval. Historical full targets are exposed development/evaluation evidence; no configuration is selected from this result.\n\n| Configuration | tIoU % | vIoU % | Severe t / v / union vs original native Source |\n|---|---:|---:|---|\n"
 for name,v in r['means'].items():
  z=r['severe_vs_Source'][name];s+=f"| {name} | {100*v['t']:.6f} | {100*v['v']:.6f} | {z['t']} / {z['v']} / {z['union']} |\n"
 s+='\nAll native-Source severe counts use >5pp losses, union counted once. SourceJointMAP is separate because native Source uses per-offset MAP followed by a physical hull.\n\n| Signed comparison | Δt pp [95% CI] | Δv pp [95% CI] | Severe t/v/union | Rescue union |\n|---|---:|---:|---|---:|\n'
 for key,z in r['paired'].items():
  e=tails[key];s+=f"| {key} | {ci(z['t'])} | {ci(z['v'])} | {e['severe_t']} / {e['severe_v']} / {e['severe_union_once']} | {e['rescue_union_once']} |\n"
 s+='\n## Duration groups\n\n| Group / signed comparison | Queries | Δt pp [95% CI] | Δv pp [95% CI] |\n|---|---:|---:|---:|\n'
 for group,g in r['timegroups'].items():
  for key,z in g['paired'].items():s+=f"| {group} / {key} | {g['queries']} | {ci(z['t'])} | {ci(z['v'])} |\n"
 s+='\n## Interpretation and costs\n\nNoPosteriorUpdate isolates temporal evidence update with the same auxiliary features and q0 joint-MAP readout. HardMembership replaces the soft event membership by the hard q0-MAP seed. EventOnly omits the background denominator without centering; EventCentered is the separately declared video-centered event-only control. NoShrink uses kappa0; UniformPrior retains the original q0 membership/evidence while changing only the final positive-support prior. FullMAP retains kappa64/beta1/context1.5/one round and the same eight expert observations.\n\n'
 if ds=='hc2':s+='The uncentered EventOnly control loses substantial temporal and video accuracy. Centering largely recovers its vIoU, with a pointwise interval crossing zero against FullMAP. Removing shrinkage **improves** mean tIoU and vIoU here, while increasing the native-Source severe union from396 (FullMAP) to467. Thus this result does not support an unconditional mean-accuracy advantage for shrinkage64. UniformPrior has a small mean difference with intervals crossing zero and a larger native-Source severe union597. The fixed method is not retuned from these exposed full-target comparisons. Soft versus hard membership has a temporal difference, while the vIoU interval crosses zero.\n\n'
 s+=f"Intervals are pointwise parent-cluster bootstrap intervals, not familywise or independent-unseen confirmation. All scalar signed outcomes, observed/unobserved effects, short/long intervals, severe losses and rescues remain in report.json, all_signed.tsv, all_signed_severe_timegroups.tsv and all_paired_tail_summary.json. The audited cached-query wall sums per worker are {json.dumps(a['worker_query_CPU_seconds'])}; these exclude setup/outer-loop overhead and may reflect shared-host execution. They are not end-to-end deployment latency. Inherited Source/expert acquisition is nonzero provenance. New Source/expert/GPU/GT scoring during this read-only export: zero.\n\nAudit: all arrays rederived exactly, all reported means recomputed, {a['SHA_checks']} parent/prediction/receipt SHA checks. The independent official score receipt and frozen protocol remain authoritative."
 (folder/'ANALYSIS.md').write_text(s);atomic(D/f'temporal_v2_{ds}_analysis_export_receipt.json',dict(status='complete_exported_verified',analysis_sha256=sha(folder/'ANALYSIS.md'),report_sha256=sha(folder/'report.json'),audit_sha256=sha(audit),code_sha256=sha(Path(__file__)),new_model=0,new_GT_scoring=0));print(ds,'exported')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--dataset',choices=COUNTS,required=True);z=p.parse_args();run(z.dataset)
